<?php
// Shared read models for the three-step upload workflow. No posting on GET.
function os_registration_stock_data($row,$batch,$plan){
 if($batch['kind']!=='Register'||$batch['status']!=='Review'||!empty($row['order_record'])||($row['action']??'')==='Removed from Upload')return [];
 $used=[];foreach($plan['orders']??[] as $prior){if((string)$prior['order']===(string)$row['order'])break;if(in_array($prior['action'],['Reserve','Register & dispatch'],true)&&!$prior['errors'])foreach($prior['totals'] as $pid=>$qty)$used[$pid]=($used[$pid]??0)+(int)$qty;}
 $out=[];foreach($row['totals']??[] as $pid=>$qty){$stock=stock_row($pid);$earlier=$used[$pid]??0;$platform=platform_qty($batch['platform'],$pid);$reserved=om_reserved($pid,$batch['platform']);$global=om_available($pid);$available=$platform-$reserved-$earlier;$warehouse=$global-$earlier;$out[]=['product'=>$stock['name'],'required'=>(int)$qty,'platform_stock'=>$platform,'reserved'=>$reserved,'earlier_upload'=>$earlier,'platform_available'=>$available,'warehouse_available'=>$warehouse,'usable'=>min($available,$warehouse),'shortage'=>max(0,(int)$qty-min($available,$warehouse))];}return $out;
}
function os_registration_stock_panel($row,$batch,$plan){
 $items=os_registration_stock_data($row,$batch,$plan);if(!$items)return;
 echo '<details class="os-stock-breakdown"'.($row['errors']?' open':'').'><summary>Stock Availability · '.e($batch['platform']).'</summary><p class="small muted">Live review only. Required is this order. Earlier in this upload is planned for valid preceding orders, not yet reserved.</p>';
 foreach($items as $item){echo '<p><b>'.e($item['product']).'</b></p><dl>';foreach(['required'=>'Required','platform_stock'=>'Platform Stock','reserved'=>'Already Reserved','earlier_upload'=>'Earlier in This Upload','platform_available'=>'Platform Available for This Order','warehouse_available'=>'Warehouse Sellable Available for This Order','usable'=>'Usable for This Order','shortage'=>'Shortage'] as $key=>$label)echo '<dt>'.e($label).'</dt><dd>'.(int)$item[$key].' pcs</dd>';echo '</dl>';}
 echo '<p class="small muted">If the product is wrong, use Correct Product / Bundle. A platform allocation transfer does not increase warehouse physical stock.</p>';if(access_page_allowed('transfers'))echo '<a class="btn secondary sm" href="?page=transfers">Open Stock Transfer</a>';echo '</details>';
}
function os_product_source_data($row,$batch){
 $data=['origin'=>'upload','lines'=>$row['lines']??[],'totals'=>$row['totals']??[],'source'=>['id'=>$batch['id'],'filename'=>$batch['filename'],'created_at'=>$batch['created_at']??'']];
 if($data['lines'])return $data;$o=$row['order_record']??null;if(!$o||empty($o['id']))return $data;
 $data['origin']='saved';$data['totals']=[];$data['source']=null;
 foreach(om_query('SELECT source_json,components_json FROM om_lines WHERE order_id=? ORDER BY id',[$o['id']]) as $saved){$line=json_decode($saved['source_json'],true);if(!is_array($line))continue;$data['lines'][]=$line;foreach(json_decode($saved['components_json'],true)?:[] as $component){$pid=(int)($component['product_id']??0);if($pid)$data['totals'][$pid]=($data['totals'][$pid]??0)+(int)($line['qty']??1)*(int)($component['per_bundle']??1);}}
 if(!empty($o['registration_id']))$data['source']=om_query('SELECT id,filename,created_at FROM om_uploads WHERE id=?',[$o['registration_id']])->fetch()?:null;
 if(!$data['lines']){foreach(om_query('SELECT f.product_id,SUM(f.qty) qty FROM om_postings m JOIN outflows f ON f.id=m.outflow_id WHERE m.order_id=? AND f.qty>0 GROUP BY f.product_id',[$o['id']]) as $posted)$data['totals'][(int)$posted['product_id']]=(int)$posted['qty'];$data['origin']='dispatch';}
 return $data;
}
function os_product_source_panel($row,$batch){
 $data=os_product_source_data($row,$batch);echo '<details class="os-product-source"><summary>View Products / Source</summary>';
 if($data['origin']!=='upload')echo '<p class="small muted">Not present in this export. Showing saved '.($data['origin']==='saved'?'registration items':'dispatch items').'; no new upload or stock movement.</p>';
 if($data['source']){$source=$data['source'];echo '<p><b>'.($data['origin']==='upload'?'Current upload':'Original registration upload').':</b> '.e($source['filename']).'<br><span class="small muted">Upload #'.(int)$source['id'].(!empty($source['created_at'])?' · '.e($source['created_at']):'').'</span></p>';if($data['origin']!=='upload'&&access_page_allowed('outflow'))echo '<a class="btn ghost sm" href="?page=outflow&amp;platform='.e($batch['platform']).'&amp;upload_id='.(int)$source['id'].'">View Original Upload</a>';}
 foreach($data['lines'] as $line){if(sm_value($line,$batch['platform'])!=='')echo '<p class="small muted">'.e(sm_field($line,$batch['platform']).': '.sm_value($line,$batch['platform'])).'</p>';if(!empty($line['mapping_basis']))echo '<p class="small muted">Mapping: '.e($line['mapping_basis']).'</p>';$name=$line['name']??$line['item']??'Product';$variation=$line['variation']??'';echo '<p>'.e($name.($variation!==''?' / '.$variation:'').' × '.($line['qty']??'Not recorded')).'</p>';if(!empty($line['sheet']))echo '<p class="small muted">'.e($line['sheet']).' · Row '.(int)($line['source_row']??$line['row']??0).'</p>';if(or_line_tracking([$line]))echo '<p class="small muted">Tracking: '.e(implode(' / ',or_line_tracking([$line]))).'</p>';}
 if($data['totals'])echo '<p><b>'.($data['origin']==='dispatch'?'Recorded dispatch quantities':'Mapped products / quantities').'</b></p>';foreach($data['totals'] as $pid=>$qty){$p=gm_products()[$pid]??null;if(!$p)$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$pid])->fetch()?:[];echo '<p>'.e(($p['master_sku']??'#'.$pid).' · '.($p['name']??'Product').' = '.$qty.' pcs').'</p>';}
 if(!$data['lines']&&!$data['totals'])echo '<p class="muted">No saved item details are available. Open Order History to investigate the original record.</p>';echo '</details>';
}
function os_category($r){if($r['action']==='Removed from Upload')return 'removed';if($r['errors']||$r['action']==='Missing from covering export')return 'checking';if($r['action']==='Excluded — not registered')return 'unregistered';if(in_array($r['action'],['Duplicate — skip','Older export — skip','Unchanged','Removed from Upload'],true))return 'unchanged';return 'update';}
function os_effect($r){if($r['errors'])return 'No posting · resolve validation';$qty=array_sum($r['totals']);return match($r['action']){'Removed from Upload'=>'Excluded by user · no status / stock change','References only'=>'Tracking/reference information only · status and stock unchanged','Register & dispatch'=>'Late dispatch −'.$qty.' pcs · physical outflow once · reserved 0','Reserve'=>'Reserve '.$qty.' pcs · physical 0','Dispatch / post'=>'−'.$qty.' pcs · first dispatch','Report for Inflow confirmation'=>(($r['order_record']['posting']??'')==='Not Posted'?'Record report · review in Order Monitoring · physical 0':'Record report · actual return in Inflow · physical 0'),'Cancel / release'=>'Release reservation · physical 0','Duplicate — skip'=>'Skip · no new record','Older export — skip'=>'Keep recorded status · no stock change','Excluded — not registered'=>'No entry / stock change','Missing from covering export'=>'Keep previous status · follow up','Cancelled after posting — review receipt/reversal'=>'No automatic stock return',default=>'No new physical movement'};}
function os_counts($rows){$n=['update'=>0,'unchanged'=>0,'unregistered'=>0,'checking'=>0,'removed'=>0];foreach($rows as $r)$n[os_category($r)]++;return $n;}
function os_exception_key($pl,$shop,$order){return 'source-'.hash('sha256',json_encode([$pl,$shop,(string)$order]));}
function os_exception_states(){ $states=[];$users=[];foreach(db()->query('SELECT id,name FROM users') as $user)$users[$user['id']]=$user['name'];foreach(db()->query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE event_type IN ('Unregistered dispatch detected','Unregistered dispatch resolved') ORDER BY e.id") as $e){$d=json_decode($e['details_json'],true);if(!$d||empty($d['key']))continue;if($e['event_type']==='Unregistered dispatch resolved'){if(isset($states[$d['key']]))$states[$d['key']]['resolved']=true;continue;}$d['event_id']=$e['id'];$d['created_at']=$e['created_at'];$d['upload_id']=$e['upload_id'];$d['owner_name']=$users[$d['owner_id']??0]??$e['actor'];$d['resolved']=false;$states[$d['key']]=$d;}return $states;}
function os_open_exceptions($platform=''){$rows=[];foreach(os_exception_states() as $d){if($d['resolved']||($platform!==''&&$d['platform']!==$platform))continue;$o=om_find($d['platform'],$d['shop'],$d['order']);if($o&&$o['posting']==='Posted')continue;$rows[]=$d;}usort($rows,fn($a,$b)=>$b['event_id']<=>$a['event_id']);return $rows;}
function os_note_excluded($b,$r){if(!in_array($r['status'],['Shipped','Delivered','Completed'],true))return;$key=os_exception_key($b['platform'],$b['shop'],$r['order']);static $known=null;if($known===null)$known=os_exception_states();$old=$known[$key]??null;if($old&&($old['snapshot']??'')>=$b['meta']['snapshot'])return;om_event(null,$b['id'],'Unregistered dispatch detected',['key'=>$key,'platform'=>$b['platform'],'shop'=>$b['shop'],'order'=>(string)$r['order'],'status'=>$r['status'],'snapshot'=>$b['meta']['snapshot'],'owner_id'=>$b['created_by'],'stock_changed'=>false]);$known[$key]=['snapshot'=>$b['meta']['snapshot']];}
function os_resolve_exception($key,$reason){om_require();$reason=process_reason($reason);$found=null;foreach(os_open_exceptions() as $r)if(hash_equals($r['key'],(string)$key)){$found=$r;break;}if(!$found)throw new Exception('Exception is already resolved or no longer open.');om_event(null,$found['upload_id'],'Unregistered dispatch resolved',['key'=>$key,'reason'=>$reason,'order'=>$found['order'],'stock_changed'=>false]);audit('Resolve unregistered dispatch','Order Monitoring',$found['order'],$reason.'; no stock changed.');return $found['platform'];}
function os_exception_report($input){$rows=[];foreach(os_open_exceptions(in_array($input['platform']??'',['Shopee','Lazada','TikTok','Website'],true)?$input['platform']:'') as $r)$rows[]=[$r['platform'],$r['shop'],(string)$r['order'],$r['status'],$r['snapshot'],$r['upload_id'],$r['owner_name'],'Needs checking · no automatic posting'];return ['title'=>'Unregistered Dispatch Exceptions','headers'=>['Platform','Shop','Order ID','Source Status','Export Snapshot','Source Upload','Responsible User','Resolution'],'rows'=>$rows,'summary'=>[],'links'=>[],'filters'=>$input,'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name'],'notes'=>['Source-file exception only. No order registration or stock posting is created.']];}
function os_validation_report($b){$rows=$b['status']==='Review'?om_plan($b)['orders']:(json_decode($b['result_json']??'{}',true)['validation']??[]);$out=[];foreach($rows as $r)$out[]=[(string)$r['order'],$r['order_record']['platform_status']??'Not registered',$r['status'],os_category($r),os_decision_label($r),array_sum($r['totals']),os_effect($r),implode(' · ',$r['errors']),implode(' / ',$r['date_details']['order_dates']??array_unique(array_column($r['lines'],'created'))),$r['date_details']['fulfillment_date']??($r['order_record']['fulfillment_date']??''),implode(' / ',$r['date_details']['shipping_dates']??array_filter(array_unique(array_column($r['lines'],'ship_at')))),$r['date_details']['shipping_source']??'',$r['posting_date']??'', $r['date_details']['posting_basis']??'', $r['date_details']['registration_recorded_at']??($r['order_record']['created_at']??''), !empty($r['date_details']['export_before_encoding'])?'Export before system encoding; verify actual fulfillment':'', $r['exclusion']['reason']??'', $r['exclusion']['user_id']??'', $r['exclusion']['at']??'',...($r['order_record']?or_report_fields($r['order_record']):[(($r['lines'][0]['reference_type']??'')==='Booking'?'Advance Fulfillment':'Regular Order'),(($r['lines'][0]['reference_type']??'')==='Booking'?$r['order']:''),'',implode(' / ',or_line_tracking($r['lines']))]),implode(' / ',array_unique(array_column($r['lines'],'source_reference_no'))),implode(' / ',array_unique(array_column($r['lines'],'mapping_basis'))),implode(' / ',array_unique(array_map(fn($line)=>sm_field($line,$b['platform']).': '.sm_value($line,$b['platform']),$r['lines'])))];return ['title'=>'Order Upload Validation #'.$b['id'],'headers'=>['Order ID','Previous Status','Uploaded Status','Category','Decision','Product Units','Inventory Effect','Validation','Order Date','Fulfillment Date','Source Shipping Date','Shipping Source Field','Validated Posting Date','Posting Date Basis','System Encoding Time','Encoding Note','Removal Reason','Removed By (User ID)','Removed At','Reference Type','Booking SN','Assigned Order ID','Tracking Numbers','Uploaded Reference','Mapping Basis','SKU Field / Value'],'rows'=>$out];}

function os_decision_label($r){return $r['action']==='Report for Inflow confirmation'?(($r['order_record']['posting']??'')==='Not Posted'?'For Order Monitoring confirmation':'For actual return follow-up'):$r['action'];}
